  "app.activeFor": "– aktiv für {join}",
  "app.tripsDisappearedAvailable": "Fahrten = verschwundene verfügbare Fahrzeuge ({v0} ≤ 40 m am selben Ort zählen nicht). Hochrechnung auf 24 h über den Tagesgang ({source}{v2}). <b>Kalibriert</b> = gemessene E-Scooter-Fahrten × Methodenfaktor aus amtlichen Berliner Zahlen (Spanne aus den Quartalswerten); Räder und E-Bikes bleiben gemessen. Flotte = Ø Fahrzeuge auf der Straße inkl. gesperrter. Ø Fahrtdauer: {v3}. Umsatz zu Listenpreisen des Standardtarifs, {v4}mal {v5}. Betreiber-Umsetzungen, die das Fahrzeug aus dem Feed nehmen, zählen als Fahrt.{v6}{v7} <b>Korrektur ×</b> ersetzt für einen Anbieter den Kalibrierfaktor (wirkt auf Rides/Fzg./Tag, Auslastung und Umsatz); die Faktoren gelten nur in diesem Browser{v8}.",
