  "app.comparisonNoFactor": "Vergleich, kein Faktor",
  "app.onlyOneOperatorOthersMay": "; nur ein Anbieter, andere können anders zählen",
  "app.tripDurationAvgEScooterTrip": "<b>Fahrtdauer.</b> Ø Fahrt E-Scooter = Mittel der Berliner Quartalswerte{v0}; gemessene Dauer (20-Min.-Raster) gilt nur darunter. Räder, E-Bikes, Lastenräder: keine amtlichen Belege, bisherige Annahmen.",
  "app.methodFactorKOfficialTrips": "<b>Methodenfaktor k.</b> Amtliche Fahrten je E-Scooter und Tag in Berlin (gleiches Quartal, sonst Vorjahresquartal, sonst jüngstes) ÷ unsere Berliner Messung über die letzten bis zu {CALIB_DAYS} Tagesdateien; k gleicht verschluckte Fahrten zwischen zwei Abrufen und Kennungswechsel aus und gilt für E-Scooter bundesweit, die Spanne folgt aus dem kleinsten und größten Quartalswert.",
  "app.plausibilityIfOperatorS": "<b>Plausibilität.</b> Liegt die gemessene Zahl der Fahrten je E-Scooter und Tag eines Anbieters in einem Gebiet über {v0} ({overFactor} × größter Berliner Quartalswert), gilt sie als Überzählung: keine Kalibrierung, nicht in Summen. k stammt nur aus plausiblen Berliner Anbietern{v2}{v3}.",
  "app.preliminaryBelowMeasurement": "<b>Vorläufig</b> unter {minDays} Messtagen oder unter {v1} % beobachteter Tagesstunden; ohne Berliner Messung oder bei k außerhalb {kMin}–{kMax} keine Kalibrierung. Eigene „Korrektur ×“ ersetzt k je Anbieter.",
  "app.coverageAndCheckOwnEScooters": "<b>Abdeckung und Prüfung.</b> Eigene E-Scooter ÷ amtliche Flotte: in Berlin Anteil an der genehmigten Flotte (Untergrenze der Feed-Abdeckung, nicht alle genehmigten Fahrzeuge fahren), in München an der aktiven Flotte; Frankfurt (Untergrenze aus Jahresfahrten und Obergrenze), Europa und Voi dienen nur dem Vergleich.",
