  "app.activeFor": "– active for {join}",
  "app.tripsDisappearedAvailable": "Trips = disappeared available vehicles ({v0} ≤ 40 m at the same spot do not count). Extrapolation to 24 h via the daily profile ({source}{v2}). <b>Calibrated</b> = measured e-scooter trips × method factor from official Berlin figures (range from the quarterly values); bikes and e-bikes stay measured. Fleet = avg. vehicles on the street incl. disabled ones. Avg. trip duration: {v3}. Revenue at list prices of the standard tariff, {v4}times {v5}. Operator rebalancing that takes the vehicle out of the feed counts as a trip.{v6}{v7} <b>Correction ×</b> replaces the calibration factor for one operator (affects trips/veh./day, utilisation and revenue); the factors apply only in this browser{v8}.",
