  "rep.calibrationMeasuredEScooter": "Calibration: measured e-scooter trips underestimate the real trips (trips between two fetches, ID rotation). The factor is the ratio of the official Berlin trips per vehicle per day to our own Berlin measurement; it applies to e-scooters everywhere, the range follows from the smallest and largest Berlin quarterly value. Bikes and e-bikes stay measured.",
